}])

const { events } = await engine.run({ units: 250, loyaltyYears: 5 })

const rules = [
  { name: 'volume-discount', when: f => f.units > 100 && f.loyaltyYears > 2,
    then: f => { f.discount = 0.10 } },
  { name: 'vip-shipping', when: f => f.vip, then: f => { f.freeShipping = true } },
]

for (const rule of rules) {
  if (rule.when(facts)) { rule.then(facts); rule.fired = true }
}
